                    self.segments.append(decoded_seg)

    @staticmethod
    def fix_path(path):
        if not path:
            return ""
        segment_str = path
        if segment_str.startswith('/'):
            segment_str = segment_str[1:]
        if segment_str.endswith('/'):
            segment_str = segment_str[:-1]
        return segment_str

    def get_segments(self):
        return self.segments

    def with_end_tag(self):
        return self._with_end_tag
