                }
            }
        }

        StringBuilder plainText = new StringBuilder();
        direction = -1;
        row = 0;
        col = 0;

        for (int i = 0; i < encryptedText.length(); i++) {
            if (row == 0 || row == rails - 1) {
                direction = -direction;
            }
            plainText.append(fence[row][col++]);
            row += direction;
        }

        return plainText.toString();
    }
