        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        count = 1
        symbol = self.board[row][col]
        for i in range(1, 5):
            new_row = row + dx * i
            new_col = col + dy * i
            if new_row < 0 or new_row >= self.board_size or new_col < 0 or new_col >= self.board_size:
                break
            if self.board[new_row][new_col] != symbol:
                break
            count += 1
        for i in range(1, 5):
