        std::deque<double> stack;
        for (const std::string& token : postfixStack) {
            if (isOperator(token[0])) {
                double b = stack.front(); stack.pop_front();
                double a = stack.front(); stack.pop_front();
                stack.push_front(_calculate(a, b, token[0]));
            } else {
