Let me analyze the Python code and translate it to C++.

Key behaviors:
1. `students` is a dict mapping name -> {name, grade, major, courses: {course: score}}
2. `add_student`: adds entry to students dict
3. `add_course_score`: only adds if student exists
4. `get_gpa`: returns float average if student exists and has courses, else None
5. `get_all_students_with_fail_course`: returns list of student names with any score < 60
6. `get_course_average`: returns float average if count > 0, else None
7. `get_top_student`: finds student with highest GPA (strictly greater than current top), returns name or None

Edge cases:
- `get_gpa` returns None if student doesn't exist or has no courses
- `get_course_average` returns None if nobody has the course
- `get_top_student` starts with top_gpa = 0, so students with GPA <= 0 won't be selected (but scores are positive, so GPA should always be positive if courses exist)
- `get_top_student` uses `>` not `>=`, so ties go to the first student found
- `add_course_score` checks `score is not None` in `get_course_average` but not in `add_course_score` itself - in Python, scores are ints so never None. The check in `get_course_average` is defensive.

In C++:
- Use `std::map` or `std::unordered_map` for dicts
- Use `std::optional` for None returns
- Use `std::vector<std::string>` for lists
- The `score is not None` check in `get_course_average` - in C++ with int scores, this is always true, so we can skip it

Let me write the C++ code:

```cpp
#include <string>
#include <map>
#include <vector>
#include <optional>
#include <numeric>

class AssessmentSystem {
public:
    struct StudentInfo {
        std::string name;
        int grade;
        std::string major;
        std::map<std::string, int> courses;
    };

private:
    std::map<std::string, StudentInfo> students;

public:
    AssessmentSystem() = default;

    void add_student(const std::string& name, int grade, const std::string& major) {
        students[name] = {name, grade, major, {}};
    }

    void add_course_score(const std::string& name, const std::string& course, int score) {
        auto it = students.find(name);
        if (it != students.end()) {
            it->second.courses[course] = score;
        }
    }

    std::optional<double> get_gpa(const std::string& name) {
        auto it = students.find(name);
        if (it != students.end() && !it->second.courses.empty()) {
            int total = 0;
            for (const auto& [c, s] : it->second.courses) {
                total += s;
            }
            return static_cast<double>(total) / it->second.courses.size();
        }
        return std::nullopt;
    }

    std::vector<std::string> get_all_students_with_fail_course() {
        std::vector<std::string> result;
        for (const auto& [name, student] : students) {
            for (const auto& [course, score] : student.courses) {
                if (score < 60) {
                    result.push_back(name);
                    break;
                }
            }
        }
        return result;
    }

    std::optional<double> get_course_average(const std::string& course) {
        int total = 0;
        int count = 0;
        for (const auto& [name, student] : students) {
            auto it = student.courses.find(course);
            if (it != student.courses.end()) {
                total += it->second;
                count++;
            }
        }
        if (count > 0) {
            return static_cast<double>(total) / count;
        }
        return std::nullopt;
    }

    std::optional<std::string> get_top_student() {
        std::optional<std::string> top_student;
        double top_gpa = 0;
        for (const auto& [name, student] : students) {
            auto gpa = get_gpa(name);
            if (gpa.has_value() && gpa.value() > top_gpa) {
                top_gpa = gpa.value();
                top_student = name;
            }
        }
        return top_student;
    }
};
