    BinaryDataProcessor(const std::string& binary_string) : binary_string(binary_string) {
        clean_non_binary_chars();
    }

    void clean_non_binary_chars() {
        binary_string.erase(
            std::remove_if(binary_string.begin(), binary_string.end(),
