- Behavior checklist:
  - Class `SQLGenerator` with `std::string table_name`.
  - `select(vector<string> fields = {}, string condition = "")`: if fields empty, "*", else comma joined. Appends " WHERE " + condition if condition not empty.
  - `insert(map<string, string> data)`: joins keys with ", ", joins values with ", " surrounded by single quotes.
  - `update(map<string, string> data, string condition)`: joins "key = 'value'" with ", ". Appends " WHERE " + condition.
  - `delete_(string condition)`: "DELETE FROM table WHERE condition;". Note: `delete` is a keyword in C++, use `delete_from` or `remove` or `delete_`. Let's use `delete_`.
  - `select_female_under_age(int age)`: condition "age < {age} AND gender = 'female'", calls `select`.
  - `select_by_age_range(int min_age, int max_age)`: condition "age BETWEEN {min_age} AND {max_age}", calls `select`.
- API replacements: `", ".join(...)` -> loop with `std::ostringstream` or `std::string` appending. Python `dict` -> `std::map<std::string, std::string>` or `std::vector<std::pair<std::string, std::string>>`. Since Python 3.7+ dicts preserve insertion order, `std::vector<std::pair>` is closer for iteration, but `std::map` is common for dicts. Let's use `std::map` or `std::vector<std::pair>`. Given SQL fields order might matter, `std::vector<std::pair<std::string, std::string>>` is safer to match Python dict iteration order.
- Edge cases: empty `fields` in `select` means `*`. Empty `condition` means no `WHERE`. Empty `data` in `insert`/`update` means empty fields/values.
- Semantic trap: Python `dict.keys()` and `dict.values()` iterate in the same order. C++ `std::map` iterates in sorted order, which breaks order. Using `std::vector<std::pair<std::string, std::string>>` preserves insertion order exactly like Python 3.7+.

Let's write the code.
```cpp
#include <string>
#include <vector>
#include <sstream>

class SQLGenerator {
public:
    std::string table_name;

    SQLGenerator(std::string table_name) : table_name(std::move(table_name)) {}

    std::string select(std::vector<std::string> fields = {}, std::string condition = "") {
        std::string fields_str = "*";
        if (!fields.empty()) {
            std::ostringstream oss;
            for (size_t i = 0; i < fields.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << fields[i];
            }
            fields_str = oss.str();
        }
        std::string sql = "SELECT " + fields_str + " FROM " + table_name;
        if (!condition.empty()) {
            sql += " WHERE " + condition;
        }
        return sql + ";";
    }

    std::string insert(std::vector<std::pair<std::string, std::string>> data) {
        std::ostringstream fields_oss, values_oss;
        for (size_t i = 0; i < data.size(); ++i) {
            if (i > 0) {
                fields_oss << ", ";
                values_oss << ", ";
            }
            fields_oss << data[i].first;
            values_oss << "'" << data[i].second << "'";
        }
        std::string sql = "INSERT INTO " + table_name + " (" + fields_oss.str() + ") VALUES (" + values_oss.str() + ")";
        return sql + ";";
    }

    std::string update(std::vector<std::pair<std::string, std::string>> data, std::string condition) {
        std::ostringstream set_oss;
        for (size_t i = 0; i < data.size(); ++i) {
            if (i > 0) set_oss << ", ";
            set_oss << data[i].first << " = '" << data[i].second << "'";
        }
        std::string sql = "UPDATE " + table_name + " SET " + set_oss.str() + " WHERE " + condition;
        return sql + ";";
    }

    std::string delete_(std::string condition) {
        std::string sql = "DELETE FROM " + table_name + " WHERE " + condition;
        return sql + ";";
    }

    std::string select_female_under_age(int age) {
        std::string condition = "age < " + std::to_string(age) + " AND gender = 'female'";
        return select({}, condition);
    }

    std::string select_by_age_range(int min_age, int max_age) {
        std::string condition = "age BETWEEN " + std::to_string(min_age) + " AND " + std::to_string(max_age);
        return select({}, condition);
    }
};
```

