#include <vector>
#include <tuple>
#include <sqlite3.h>
#include <stdexcept>

struct StudentData {
    std::string name;
    int age;
    std::string gender;
    int grade;
};

class StudentDatabaseProcessor {
private:
    std::string database_name;

public:
    StudentDatabaseProcessor(const std::string& database_name)
        : database_name(database_name) {}

    void create_student_table() {
        sqlite3* db;
        int rc = sqlite3_open(database_name.c_str(), &db);
        if (rc != SQLITE_OK) {
            std::string err = sqlite3_errmsg(db);
            sqlite3_close(db);
            throw std::runtime_error("Cannot open database: " + err);
        }

        const char* create_table_query = R"(
        CREATE TABLE IF NOT EXISTS students (
            id INTEGER PRIMARY KEY,
            name TEXT,
            age INTEGER,
            gender TEXT,
            grade INTEGER
        )
        )";

        char* errMsg = nullptr;
        rc = sqlite3_exec(db, create_table_query, nullptr, nullptr, &errMsg);
        if (rc != SQLITE_OK) {
            std::string error = errMsg;
            sqlite3_free(errMsg);
            sqlite3_close(db);
            throw std::runtime_error("SQL error: " + error);
        }

        sqlite3_close(db);
    }

    void insert_student(const StudentData& student_data) {
