        sqlite3_bind_int(stmt, 2, student_data.age);
        sqlite3_bind_text(stmt, 3, student_data.gender.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_int(stmt, 4, student_data.grade);

