        if (it != inventory.end()) {
            it->second.quantity += quantity;
        }
    }

    std::optional<int> get_product_quantity(int product_id) {
        auto it = inventory.find(product_id);
        if (it != inventory.end()) {
            return it->second.quantity;
        }
        return std::nullopt;
    }

