```cpp
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>
#include "tinyxml2.h"

class XMLProcessor {
private:
    std::string file_name;
    tinyxml2::XMLDocument doc;
    tinyxml2::XMLElement* root;

    void find_elements_recursive(tinyxml2::XMLElement* parent, const std::string& name, std::vector<tinyxml2::XMLElement*>& results) {
        for (tinyxml2::XMLElement* child = parent->FirstChildElement(); child != nullptr; child = child->NextSiblingElement()) {
            if (child->Name() == name) {
                results.push_back(child);
            }
            find_elements_recursive(child, name, results);
        }
    }

public:
    XMLProcessor(const std::string& file_name) : file_name(file_name), root(nullptr) {}

    tinyxml2::XMLElement* read_xml() {
        if (doc.LoadFile(file_name.c_str()) != tinyxml2::XML_SUCCESS) {
            root = nullptr;
            return nullptr;
        }
        root = doc.RootElement();
        return root;
    }

    bool write_xml(const std::string& file_name) {
        if (root == nullptr) return false;
        try {
