            // Actually, Python's ET.ElementTree(self.root).write() writes from the root element
            // In tinyxml2, we can just save the document
            return doc.SaveFile(file_name.c_str()) == tinyxml2::XML_SUCCESS;
        } catch (...) {
            return false;
        }
    }

    bool process_xml_data(const std::string& file_name) {
        if (root == nullptr) return false;
        // Iterate all 'item' elements (descendants, not just direct children)
        std::vector<tinyxml2::XMLElement*> items;
        find_elements_recursive(root, "item", items);
